do $$
begin
  if (select count(*) from nueva_lista_lunas) <> 486 then
    raise exception 'La lista de lunas no contiene 486 productos';
  end if;
  if (select count(*) from public.empresas where nombre in ('Shuvisión', 'Focus')) <> 2 then
    raise exception 'No se encontraron exactamente Shuvisión y Focus';
  end if;
end $$;

update public.productos_catalogo
set activo = false, actualizado_en = now()
where categoria = 'lente' and activo
  and empresa_id in (select id from public.empresas where nombre in ('Shuvisión', 'Focus'));

insert into public.productos_catalogo
  (empresa_id, codigo, nombre, categoria, clasificacion, diseno, linea, material, indice, tecnologia,
   costo_referencial, precio_venta, precio_venta_2, precio_convenio, controla_inventario, activo)
select e.id, 'LP-20261013-' || lpad(l.n::text, 3, '0'),
  concat_ws(' · ', initcap(l.diseno) || ' ' || l.linea, l.material || ' ' || l.indice, l.tecnologia),
  'lente', l.diseno, l.diseno, l.linea, l.material, l.indice::numeric, l.tecnologia,
  l.costo::numeric, l.mayor::numeric, l.menor::numeric, l.convenio::numeric, false, true
from public.empresas e cross join nueva_lista_lunas l
where e.nombre in ('Shuvisión', 'Focus')
on conflict (empresa_id, codigo) do update set
  nombre = excluded.nombre, categoria = excluded.categoria, clasificacion = excluded.clasificacion,
  diseno = excluded.diseno, linea = excluded.linea, material = excluded.material, indice = excluded.indice,
  tecnologia = excluded.tecnologia, costo_referencial = excluded.costo_referencial,
  precio_venta = excluded.precio_venta, precio_venta_2 = excluded.precio_venta_2,
  precio_convenio = excluded.precio_convenio, controla_inventario = false, activo = true,
  actualizado_en = now();
